# same-name, same-depth duplicates cannot exist in one dict, so use a Mapping
class DupMapping:
    def __init__(self, items):
        self._items = items
    def get(self, key, default=None):
        for k, v in self._items:
            if k == key:
                return v
        return default
    def items(self):
        return iter(self._items)
