class Recorder(RequestMethods):
    def __init__(self):
        super().__init__()
        self.calls = []
    def urlopen(self, method, url, body=None, headers=None, encode_multipart=True, multipart_boundary=None, **kw):
        self.calls.append((method, url, body, dict(headers or {}), kw))
        return body

